CREATE TABLE `velix_claim_evidence` (`id` text PRIMARY KEY NOT NULL, `claim_id` text NOT NULL REFERENCES `velix_editorial_claims`(`id`) ON DELETE CASCADE, `reference_id` text REFERENCES `velix_media_references`(`id`) ON DELETE SET NULL, `url` text NOT NULL, `title` text NOT NULL DEFAULT '', `publisher` text NOT NULL DEFAULT '', `published_at` text, `excerpt` text NOT NULL DEFAULT '', `confidence` real NOT NULL DEFAULT 0, `classification` text NOT NULL, `status` text NOT NULL DEFAULT 'candidate', `note` text, `decided_at` text, `created_at` text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')))